questions.explanation:
Design first, code second:
1. Core data structure: rope (production) or gap buffer (interview-friendly) — for interview, use a simple string + cursor index; note the perf ceiling.
2. Operations: `insert(ch)`, `delete()`, `moveLeft()`, `moveRight()`.
3. Undo: command pattern — stack of {type, position, char} operations.
4. Bind to DOM: contentEditable div + keydown handler.

```js
class Editor {
  constructor() { this.buf = ''; this.cursor = 0; this.undoStack = []; }
  insert(ch) {
    this.buf = this.buf.slice(0, this.cursor) + ch + this.buf.slice(this.cursor);
    this.cursor++;
    this.undoStack.push({ type: 'insert', pos: this.cursor - 1, ch });
  }
  delete() {
    if (this.cursor === 0) return;
    const ch = this.buf[this.cursor - 1];
    this.buf = this.buf.slice(0, this.cursor - 1) + this.buf.slice(this.cursor);
    this.cursor--;
    this.undoStack.push({ type: 'delete', pos: this.cursor, ch });
  }
  moveLeft() { if (this.cursor > 0) this.cursor--; }
  moveRight() { if (this.cursor < this.buf.length) this.cursor++; }
  undo() {
    const op = this.undoStack.pop();
    if (!op) return;
    if (op.type === 'insert') { this.buf = this.buf.slice(0, op.pos) + this.buf.slice(op.pos + 1); this.cursor = op.pos; }
    else { this.buf = this.buf.slice(0, op.pos) + op.ch + this.buf.slice(op.pos); this.cursor = op.pos + 1; }
  }
}
```
Narrate: 'For a 10k-char doc, string ops are O(n). Production uses a rope tree for O(log n). For the interview I'll keep string, note the ceiling.'
Follow-ups they'll ask: multi-cursor, syntax highlighting (tokenize + render), find/replace (KMP), collaboration (OT or CRDT).

```js
const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

const board = Array(9).fill(' ');
let turn = 'X';
const wins = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];

const render = () => console.log(board.map((c, i) => c === ' ' ? i : c).reduce((s, c, i) => s + c + ((i+1)%3 ? ' | ' : '\n' + (i<8 ? '---------\n' : '')), ''));
const winner = () => wins.find(w => board[w[0]] !== ' ' && w.every(i => board[i] === board[w[0]]));

const prompt = () => {
  render();
  rl.question(`${turn}'s move (0-8): `, ans => {
    const i = +ans;
    if (i < 0 || i > 8 || board[i] !== ' ') return prompt();
    board[i] = turn;
    if (winner()) { render(); console.log(`${turn} wins`); rl.close(); return; }
    if (board.every(c => c !== ' ')) { render(); console.log('tie'); rl.close(); return; }
    turn = turn === 'X' ? 'O' : 'X';
    prompt();
  });
};
prompt();
```
Narrate: 'Board as flat 9-array — easier win-check via 8 lines. Winner check O(1) since fixed lines.'

```js
function cleanStack(raw) {
  const lines = raw.split('\n').map(l => l.trim()).filter(Boolean);
  const out = [];
  for (const line of lines) {
    if (out.length && out[out.length - 1].line === line) out[out.length - 1].count++;
    else out.push({ line, count: 1 });
  }
  return out.map(f => f.count > 1 ? `${f.line} (×${f.count})` : f.line).join('\n');
}
```
Narrate: 'Frame line identity by exact match. Consecutive dedupe collapses recursion loops. Non-consecutive dedupe would lose call order — check with interviewer.'

```js
function topIps(logText, k = 10) {
  const cnt = new Map();
  for (const line of logText.split('\n')) {
    const ip = line.match(/^(\d+\.\d+\.\d+\.\d+)/)?.[1];
    if (ip) cnt.set(ip, (cnt.get(ip) || 0) + 1);
  }
  return [...cnt.entries()].sort((a, b) => b[1] - a[1]).slice(0, k);
}
```
Stream version for huge files:
