const readline = require('readline');
async function topIpsStream(path, k = 10) {
  const cnt = new Map();
  const rl = readline.createInterface({ input: fs.createReadStream(path) });
  for await (const line of rl) {
    const ip = line.match(/^(\S+)/)?.[1];
    if (ip) cnt.set(ip, (cnt.get(ip) || 0) + 1);
  }
  return [...cnt.entries()].sort((a, b) => b[1] - a[1]).slice(0, k);
}
```
Narrate: 'Streaming handles GB-scale logs without loading into memory.'

```js
function dedupeCsv(rows) {
  const byEmail = new Map();
  for (const r of rows) {
    const prev = byEmail.get(r.email);
    if (!prev || new Date(r.updated_at) > new Date(prev.updated_at)) byEmail.set(r.email, r);
  }
  return [...byEmail.values()];
}
```
Edge cases to name: case-sensitivity on email (normalize .toLowerCase().trim()), missing updated_at (skip or treat as epoch 0), tie-breaks (keep last-seen).

```js
function createLimiter(N, R) {
  const buckets = new Map();
  return function allow(key) {
    const now = Date.now();
    const b = buckets.get(key) || { tokens: N, last: now };
    const elapsed = (now - b.last) / 1000;
    b.tokens = Math.min(N, b.tokens + elapsed * R);
    b.last = now;
    if (b.tokens < 1) { buckets.set(key, b); return false; }
    b.tokens -= 1;
    buckets.set(key, b);
    return true;
  };
}
```
Edge cases: clock skew (monotonic clock), burst behavior, evict inactive buckets (TTL sweep).

```js
class Shortener {
  constructor() { this.map = new Map(); this.reverse = new Map(); }
  shorten(url) {
    if (this.reverse.has(url)) return this.reverse.get(url);
    let code;
    do { code = Math.random().toString(36).slice(2, 8); } while (this.map.has(code));
    this.map.set(code, url); this.reverse.set(url, code);
    return code;
  }
  resolve(code) { return this.map.get(code); }
}
```
Follow-ups: base62 for readability, incremental counter to avoid collision loops at scale, DB persistence, expiry.

```js
function diff(a, b, path = '', out = { added: {}, removed: {}, changed: {} }) {
  const ak = new Set(Object.keys(a || {})), bk = new Set(Object.keys(b || {}));
  for (const k of bk) if (!ak.has(k)) out.added[path + k] = b[k];
  for (const k of ak) {
    const p = path + k;
    if (!bk.has(k)) out.removed[p] = a[k];
    else if (typeof a[k] === 'object' && a[k] && typeof b[k] === 'object' && b[k]) diff(a[k], b[k], p + '.', out);
    else if (a[k] !== b[k]) out.changed[p] = { from: a[k], to: b[k] };
  }
  return out;
}
```
Edge cases: arrays (index vs identity), null vs undefined, dates.

```js
class PubSub {
  constructor() { this.topics = new Map(); this.byId = new Map(); this.id = 0; }
  subscribe(topic, fn) {
    const id = ++this.id;
    if (!this.topics.has(topic)) this.topics.set(topic, new Set());
    this.topics.get(topic).add(id);
    this.byId.set(id, { topic, fn });
    return id;
  }
  unsubscribe(id) {
    const sub = this.byId.get(id);
    if (!sub) return;
    this.topics.get(sub.topic).delete(id);
    this.byId.delete(id);
  }
  publish(topic, msg) {
    const subs = this.topics.get(topic);
    if (!subs) return;
    for (const id of subs) { const s = this.byId.get(id); try { s.fn(msg); } catch (e) { console.error(e); } }
  }
}
```
Extensions: wildcards ('user.*'), async handlers with backpressure, historical replay.

