```js
class LRU {
  constructor(cap) { this.cap = cap; this.m = new Map(); }
  get(k) {
    if (!this.m.has(k)) return -1;
    const v = this.m.get(k);
    this.m.delete(k); this.m.set(k, v);
    return v;
  }
  put(k, v) {
    if (this.m.has(k)) this.m.delete(k);
    else if (this.m.size >= this.cap) this.m.delete(this.m.keys().next().value);
    this.m.set(k, v);
  }
}
```
Production version: doubly-linked list + hash map. Discuss both.

```js
class Door {
  constructor() { this.state = 'closed'; this.paused = false; this.log = []; }
  _t(newState) { this.log.push(`${this.state} → ${newState}`); this.state = newState; }
  press() {
    if (this.paused) return;
    if (this.state === 'closed') this._t('opening');
    else if (this.state === 'open') this._t('closing');
    else if (this.state === 'opening') this._t('closing');
    else if (this.state === 'closing') this._t('opening');
  }
  obstacle() {
    if (this.state === 'closing') this._t('opening');
  }
  pause() { this.paused = true; }
  resume() { this.paused = false; }
  tick() {
    if (this.paused) return;
    if (this.state === 'opening') this._t('open');
    else if (this.state === 'closing') this._t('closed');
  }
}
```
Andela weights: enumerate every state × event combination in your tests. Write 8-10 assertions before you 'finish'.

```js
class Elevator {
  constructor(floors, capacity) { this.floors = floors; this.capacity = capacity; this.floor = 1; this.dir = 'idle'; this.riders = []; this.queue = []; this.emergency = false; }
  request(from, to) { this.queue.push({ from, to }); this._plan(); }
  emergencyStop() { this.emergency = true; this.dir = 'idle'; this.queue = []; }
  reset() { this.emergency = false; }
  step() {
    if (this.emergency) return;
    if (this.dir === 'up') this.floor++;
    else if (this.dir === 'down') this.floor--;
    this._handleFloor();
    this._plan();
  }
  _handleFloor() {
    this.riders = this.riders.filter(r => { if (r.to === this.floor) return false; return true; });
    const boarding = this.queue.filter(q => q.from === this.floor && this.riders.length < this.capacity);
    for (const b of boarding) { this.riders.push(b); this.queue.splice(this.queue.indexOf(b), 1); }
  }
  _plan() {
    if (!this.riders.length && !this.queue.length) { this.dir = 'idle'; return; }
    const targets = [...this.riders.map(r => r.to), ...this.queue.map(q => q.from)];
    const above = targets.some(t => t > this.floor), below = targets.some(t => t < this.floor);
    if (this.dir === 'up' && above) return;
    if (this.dir === 'down' && below) return;
    this.dir = above ? 'up' : below ? 'down' : 'idle';
  }
}
```
Test each: pickup order, direction reversal, capacity fill, emergency stop clears queue.

```js
class Vending {
  constructor(stock, prices) { this.stock = { ...stock }; this.prices = prices; this.balance = 0; }
  insertCoin(n) { this.balance += n; return this.balance; }
  select(item) {
    if (!this.stock[item]) return { error: 'out-of-stock' };
    if (this.balance < this.prices[item]) return { error: 'insufficient', need: this.prices[item] - this.balance };
    this.stock[item]--;
    const change = this.balance - this.prices[item];
    this.balance = 0;
    return { dispensed: item, change };
  }
  cancel() { const r = this.balance; this.balance = 0; return r; }
}
```
Tests: out-of-stock, exact amount, change, cancel-refund, multi-select without cancel.

```js
class ATM {
  constructor(pin, balance, dailyLimit = 500) { this.pin = pin; this.balance = balance; this.dailyLimit = dailyLimit; this.withdrawnToday = 0; this.attempts = 0; this.locked = false; this.authed = false; }
  login(pin) {
    if (this.locked) return { error: 'locked' };
    if (pin === this.pin) { this.authed = true; this.attempts = 0; return { ok: true }; }
    this.attempts++;
    if (this.attempts >= 3) this.locked = true;
    return { error: 'wrong-pin', attemptsLeft: 3 - this.attempts };
  }
  balance() { return this.authed ? this.balance : { error: 'not-authed' }; }
  withdraw(amount) {
    if (!this.authed) return { error: 'not-authed' };
    if (amount % 20 !== 0) return { error: 'multiple-of-20' };
    if (amount > this.balance) return { error: 'insufficient' };
    if (this.withdrawnToday + amount > this.dailyLimit) return { error: 'daily-limit' };
    this.balance -= amount; this.withdrawnToday += amount;
    return { dispensed: amount, remaining: this.balance };
  }
}
```
Tests: 3 wrong PINs → lock, exact daily limit, multi-withdraw hitting limit, non-20 amount.

```js
class Intersection {
  constructor(cycleSec) { this.cycleSec = cycleSec; this.state = 'NS-green'; this.t = 0; this.emergency = false; }
  tick() {
    if (this.emergency) { this.state = 'all-red'; return; }
    this.t++;
    if (this.state === 'NS-green' && this.t >= this.cycleSec) { this._t('NS-yellow'); }
    else if (this.state === 'NS-yellow' && this.t >= 3) { this._t('EW-green'); }
    else if (this.state === 'EW-green' && this.t >= this.cycleSec) { this._t('EW-yellow'); }
    else if (this.state === 'EW-yellow' && this.t >= 3) { this._t('NS-green'); }
  }
  _t(s) { this.state = s; this.t = 0; }
  emergencyOn() { this.emergency = true; }
  emergencyOff() { this.emergency = false; this._t('NS-green'); }
}
```
Test each phase transition + emergency preempt + resume.

```js
const fs = require('fs');
const { pipeline } = require('stream/promises');

async function copy(src, dest) {
  let copied = 0;
  const rs = fs.createReadStream(src);
  rs.on('data', c => {
    copied += c.length;
    if (copied % (100 * 1024 * 1024) < c.length) console.log(`${(copied / 1e6).toFixed(0)} MB`);
  });
  const ws = fs.createWriteStream(dest);
  await pipeline(rs, ws);
  console.log('done');
}
```
`pipeline` handles backpressure + errors. `fs.readFile` would OOM on 5GB.

```js
// main.js
const { Worker } = require('worker_threads');
function hash(file) {
  return new Promise((res, rej) => {
    const w = new Worker('./hash-worker.js', { workerData: file });
    w.once('message', res);
    w.once('error', rej);
  });
}
async function hashAll(files) {
  return await Promise.all(files.map(hash));
}

// hash-worker.js
const { workerData, parentPort } = require('worker_threads');
const crypto = require('crypto');
const fs = require('fs');
const h = crypto.createHash('sha256');
fs.createReadStream(workerData).on('data', c => h.update(c)).on('end', () => parentPort.postMessage(h.digest('hex')));
```
Worker pool would be cleaner for 1000+ files. Note: for pure I/O-bound work, plain streams are fine — workers help only for CPU-bound.

```js
const fs = require('fs');
const readline = require('readline');

async function filter(inp, out) {
  const rl = readline.createInterface({ input: fs.createReadStream(inp) });
  const ws = fs.createWriteStream(out);
  for await (const line of rl) {
    try {
      const r = JSON.parse(line);
      if (r.price > 100) { if (!ws.write(JSON.stringify(r) + '\n')) await new Promise(res => ws.once('drain', res)); }
    } catch (e) { /* skip malformed */ }
  }
  ws.end();
}
```
Backpressure via `ws.write` return + drain event. Constant memory.

