let shuttingDown = false; let inflight = 0;

process.on('SIGTERM', async () => {
  shuttingDown = true;
  console.log('SIGTERM: draining');
  const deadline = Date.now() + 30000;
  while (inflight > 0 && Date.now() < deadline) await new Promise(r => setTimeout(r, 100));
  if (inflight > 0) console.error(`force-exit with ${inflight} in flight`);
  process.exit(0);
});

async function loop() {
  while (!shuttingDown) {
    const job = await queue.pop();
    if (!job) continue;
    inflight++;
    try { await process(job); } finally { inflight--; }
  }
}
loop();
```
